const {vec} = NMath;
const {vertices, faces} = await IO.loadMesh("/assets/bunny.obj");

const clamp = x => Math.min(1, Math.max(0, x));
const normalizeVectors = vectors => {
    const mean = vectors.reduce((sum, value) => sum.add(value), vec.zero(3)).scale(1 / vectors.length);
    const centered = vectors.map(value => value.sub(mean));
    const max = centered.reduce((largest, value) => Math.max(largest, value.map(Math.abs).fold(0, (a, x) => Math.max(a, x))), 0);
    const scaled = max === 0 ? centered : centered.map(value => value.scale(1 / max));
    return scaled.map(({components: [x, y, z]}) => vec(z, x, y));
};

let pts = vertices.map(vertex => vec(...vertex));
pts = normalizeVectors(pts);

let coords = [];
for(let d = 0; d < 3; d++){
  let aux = [];
  for(let i = 0; i < pts.length; i++){
    aux.push(pts[i].components[d]);
  }
  coords.push(vec(...aux));
}

const graph = Graph.knn(pts, 4, (x, y) => x.sub(y).length());
const sigma = 0.005;
const laplacian = graph.laplacian((i, j) => Math.exp(-i.vertex.sub(j.vertex).squareLength() / sigma));
const k = Math.min(50, pts.length);
const {eigenvectors} = laplacian.eigen({maxFirst: false, k});

const points = pts.map(x => x.toArray());
const pointPlot = IO.plotPointCloud(points,{color:[0.5,0.5,0.5]});
const rasterPlot = IO.raster(points, faces, {color:[0.5,0.5,0.5]});

const updateEigenvector = index => {
    const newCoords = [];    
    for (let d = 0; d < 3; d++) {
      let newCoord = vec.zero(pts.length);
      for (let j = 0; j < index; j++) { 
        newCoord = newCoord.add(
                    eigenvectors[j].scale(eigenvectors[j].dot(coords[d]))        
        );
      }      
      newCoords.push(newCoord);    
    }

    const newPoints = pts.map((_, i) => 
        [newCoords[0].components[i], newCoords[1].components[i], newCoords[2].components[i]]
    )
    pointPlot.update(newPoints, {color: [0.5,0.5,0.5]});
    pointPlot.render();
    rasterPlot.update(newPoints, faces, {color: [0.5,0.5,0.5]});
    rasterPlot.render();
};

const ui = IO.UI(
    {type: "group", value: () => [
        {type: "canvas", value: () => pointPlot},
        {type: "canvas", value: () => rasterPlot},
    ]},
    {type: "slider", value: () => ({
        min: 0,
        max: k,
        step: 1,
        value: 0,
        title: "Eigenvector:",
        onChange: value => updateEigenvector(Math.round(value)),
    })},
);
ui;
